using System.Diagnostics;
using System.Runtime.InteropServices;
using Microsoft.Win32;

namespace BluetoothGamepadBridge;

/// <summary>
/// Intercepts and swallows synthetic keystrokes and mouse movements/clicks injected into
/// Windows OS by background mappers such as Steam's "Desktop Layout" or Windows Game Bar.
/// 
/// Runs an STA thread with a dedicated Win32 message pump (GetMessage/DispatchMessage),
/// which is mandatory on Windows for low-level hooks (WH_KEYBOARD_LL, WH_MOUSE_LL).
/// 
/// Crucially: Physical keyboard and mouse events generated by human hands are NOT injected
/// (flags == 0), so they pass through completely untouched, allowing normal PC usage.
/// </summary>
public static class InputInterceptor
{
    private const int WH_KEYBOARD_LL = 13;
    private const int WH_MOUSE_LL = 14;
    private const uint WM_QUIT = 0x0012;

    // Injected flags in KBDLLHOOKSTRUCT
    private const uint LLKHF_INJECTED = 0x00000001;
    private const uint LLKHF_LOWER_IL_INJECTED = 0x00000002;

    // Injected flags in MSLLHOOKSTRUCT
    private const uint LLMHF_INJECTED = 0x00000001;
    private const uint LLMHF_LOWER_IL_INJECTED = 0x00000002;

    [StructLayout(LayoutKind.Sequential)]
    private struct POINT
    {
        public int x;
        public int y;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct KBDLLHOOKSTRUCT
    {
        public uint vkCode;
        public uint scanCode;
        public uint flags;
        public uint time;
        public UIntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct MSLLHOOKSTRUCT
    {
        public POINT pt;
        public uint mouseData;
        public uint flags;
        public uint time;
        public UIntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct MSG
    {
        public IntPtr hwnd;
        public uint message;
        public UIntPtr wParam;
        public IntPtr lParam;
        public uint time;
        public POINT pt;
    }

    private delegate IntPtr HookProc(int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, HookProc lpfn, IntPtr hMod, uint dwThreadId);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string? lpModuleName);

    [DllImport("kernel32.dll")]
    private static extern uint GetCurrentThreadId();

    [DllImport("user32.dll")]
    private static extern int GetMessage(out MSG lpMsg, IntPtr hWnd, uint wMsgFilterMin, uint wMsgFilterMax);

    [DllImport("user32.dll")]
    private static extern bool TranslateMessage(ref MSG lpMsg);

    [DllImport("user32.dll")]
    private static extern IntPtr DispatchMessage(ref MSG lpMsg);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool PostThreadMessage(uint idThread, uint Msg, UIntPtr wParam, IntPtr lParam);

    private static IntPtr _kbdHookId = IntPtr.Zero;
    private static IntPtr _mouseHookId = IntPtr.Zero;
    private static HookProc? _kbdProc;
    private static HookProc? _mouseProc;
    private static Thread? _hookThread;
    private static uint _hookThreadId;

    public static bool IsEnabled { get; private set; }
    public static long InterceptedKeysCount { get; private set; }
    public static long InterceptedMouseEventsCount { get; private set; }

    private static int? _originalGameBarNexusSetting;

    public static void Enable()
    {
        if (IsEnabled) return;

        // 1. Suppress Xbox Game Bar Guide button capture in Windows
        try
        {
            using var key = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\GameBar", true);
            if (key != null)
            {
                object? val = key.GetValue("UseNexusForGameBarEnabled");
                if (val is int intVal)
                {
                    _originalGameBarNexusSetting = intVal;
                }
                key.SetValue("UseNexusForGameBarEnabled", 0, RegistryValueKind.DWord);
            }
        }
        catch { }

        // 2. Start dedicated STA thread with Win32 message pump for WH_KEYBOARD_LL and WH_MOUSE_LL
        var readyEvent = new ManualResetEventSlim(false);

        _hookThread = new Thread(() =>
        {
            try
            {
                _hookThreadId = GetCurrentThreadId();
                _kbdProc = KeyboardHookCallback;
                _mouseProc = MouseHookCallback;

                using var curProcess = Process.GetCurrentProcess();
                using var curModule = curProcess.MainModule;
                IntPtr moduleHandle = GetModuleHandle(curModule?.ModuleName);

                _kbdHookId = SetWindowsHookEx(WH_KEYBOARD_LL, _kbdProc, moduleHandle, 0);
                _mouseHookId = SetWindowsHookEx(WH_MOUSE_LL, _mouseProc, moduleHandle, 0);

                IsEnabled = (_kbdHookId != IntPtr.Zero);
            }
            catch
            {
                IsEnabled = false;
            }
            finally
            {
                readyEvent.Set();
            }

            // Dedicated Win32 Message Pump: required for low-level hooks to receive messages
            while (GetMessage(out MSG msg, IntPtr.Zero, 0, 0) > 0)
            {
                TranslateMessage(ref msg);
                DispatchMessage(ref msg);
            }

            if (_kbdHookId != IntPtr.Zero)
            {
                UnhookWindowsHookEx(_kbdHookId);
                _kbdHookId = IntPtr.Zero;
            }
            if (_mouseHookId != IntPtr.Zero)
            {
                UnhookWindowsHookEx(_mouseHookId);
                _mouseHookId = IntPtr.Zero;
            }
        })
        {
            IsBackground = true,
            Name = "InputInterceptorMessagePump"
        };

        _hookThread.SetApartmentState(ApartmentState.STA);
        _hookThread.Start();
        readyEvent.Wait(2000);
    }

    public static void Disable()
    {
        if (!IsEnabled) return;

        // Restore GameBar setting if modified
        try
        {
            if (_originalGameBarNexusSetting.HasValue)
            {
                using var key = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\GameBar", true);
                key?.SetValue("UseNexusForGameBarEnabled", _originalGameBarNexusSetting.Value, RegistryValueKind.DWord);
            }
        }
        catch { }

        // Terminate hook thread message loop cleanly
        if (_hookThreadId != 0)
        {
            PostThreadMessage(_hookThreadId, WM_QUIT, UIntPtr.Zero, IntPtr.Zero);
            _hookThread?.Join(1000);
            _hookThreadId = 0;
            _hookThread = null;
        }

        _kbdProc = null;
        _mouseProc = null;
        IsEnabled = false;
    }

    private static IntPtr KeyboardHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0)
        {
            var hookStruct = Marshal.PtrToStructure<KBDLLHOOKSTRUCT>(lParam);

            // Check if this keystroke was injected by software (Steam Desktop Layout, Game Bar, virtual mappers)
            bool isInjected = (hookStruct.flags & LLKHF_INJECTED) != 0 ||
                              (hookStruct.flags & LLKHF_LOWER_IL_INJECTED) != 0;

            if (isInjected)
            {
                InterceptedKeysCount++;
                // Return 1 to swallow the event so Windows OS and desktop never see it!
                return (IntPtr)1;
            }
        }

        return CallNextHookEx(_kbdHookId, nCode, wParam, lParam);
    }

    private static IntPtr MouseHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0)
        {
            var hookStruct = Marshal.PtrToStructure<MSLLHOOKSTRUCT>(lParam);

            // Check if this mouse move/click was injected by software (Steam Desktop Layout moving cursor)
            bool isInjected = (hookStruct.flags & LLMHF_INJECTED) != 0 ||
                              (hookStruct.flags & LLMHF_LOWER_IL_INJECTED) != 0;

            if (isInjected)
            {
                InterceptedMouseEventsCount++;
                // Return 1 to swallow the event so cursor does NOT move and clicks are NOT passed to Windows!
                return (IntPtr)1;
            }
        }

        return CallNextHookEx(_mouseHookId, nCode, wParam, lParam);
    }
}
